{
  "items": [
    {
      "name": "MvPolynomial.pderiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type v} → [inst : CommSemiring R] → σ → Derivation R (MvPolynomial σ R) (MvPolynomial σ R)"
    },
    {
      "name": "MvPolynomial.pderiv_X_self",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] (i : σ), (MvPolynomial.pderiv i) (MvPolynomial.X i) = 1"
    },
    {
      "name": "LaurentSeries.derivative_iterate",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V] (k : ℕ)\n  (f : LaurentSeries V), (⇑(LaurentSeries.derivative R))^[k] f = k.factorial • (LaurentSeries.hasseDeriv R k) f"
    },
    {
      "name": "MvPolynomial.pderiv_def",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (i : σ),\n  MvPolynomial.pderiv i = MvPolynomial.mkDerivation R (Pi.single i 1)"
    },
    {
      "name": "MvPolynomial.pderiv_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} {a : R} {s : σ →₀ ℕ} [inst : CommSemiring R] {i : σ},\n  (MvPolynomial.pderiv i) ((MvPolynomial.monomial s) a) = (MvPolynomial.monomial (s - Finsupp.single i 1)) (a * ↑(s i))"
    },
    {
      "name": "MvPolynomial.mkDerivation",
      "module_name": "Mathlib.Algebra.MvPolynomial.Derivation",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  (R : Type u_2) →\n    {A : Type u_3} →\n      [inst : CommSemiring R] →\n        [inst_1 : AddCommMonoid A] →\n          [inst_2 : Module R A] →\n            [inst_3 : Module (MvPolynomial σ R) A] →\n              [IsScalarTower R (MvPolynomial σ R) A] → (σ → A) → Derivation R (MvPolynomial σ R) A"
    },
    {
      "name": "LaurentSeries.hasseDeriv",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "definition",
      "type": "(R : Type u_2) →\n  {V : Type u_3} →\n    [inst : AddCommGroup V] → [inst_1 : Semiring R] → [inst_2 : Module R V] → ℕ → LaurentSeries V →ₗ[R] LaurentSeries V"
    }
  ]
}
